// LC 739：栈内存下标，栈底到栈顶对应温度递减。当前温度严格更高时弹出并结算天数。
// 换题：下一个更小把 while 中的 > 改成 <；相等也要弹出则改成 >=。要距离或宽度时不能只存值。
static int[] dailyTemperatures(int[] temperatures) {
    int n = temperatures.length;
    int[] ans = new int[n];
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0;
    i < n;
    i++) {
        while (!st.isEmpty() && temperatures[i] > temperatures[st.peek()]) {
            int j = st.pop();
            ans[j] = i - j;
        }
        st.push(i);
    }
    return ans;
}

// LC 239：队列存下标，队头到队尾对应值递减，队头就是窗口最大值。
// 先丢掉下标 <= i-k 的过期队头，再从队尾丢掉比当前值更小的候选（相等也丢，留下更靠右的）。
// 换题：窗口最小值把 <= 改成 >=。
static int[] maxSlidingWindow(int[] nums, int k) {
    int n = nums.length;
    int[] ans = new int[n - k + 1];
    Deque<Integer> dq = new ArrayDeque<>();
    for (int i = 0;
    i < n;
    i++) {
        while (!dq.isEmpty() && dq.peekFirst() <= i - k) {
            dq.pollFirst();
        }
        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) {
            dq.pollLast();
        }
        dq.offerLast(i);
        if (i >= k - 1) {
            ans[i - k + 1] = nums[dq.peekFirst()];
        }
    }
    return ans;
}

// LC 20：左括号入栈，右括号必须与栈顶同类型；栈空或类型不同即非法，扫完栈必须为空。
// 换题：带优先级时，类型匹配后再比较等级，约定 {} > [] > ()，内层等级不能高于外层。
static boolean isValid(String s) {
    Deque<Character> st = new ArrayDeque<>();
    for (int i = 0;
    i < s.length();
    i++) {
        char c = s.charAt(i);
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else {
            if (st.isEmpty()) {
                return false;
            }
            char open = st.pop();
            if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.isEmpty();
}

// LC 227：加减先入栈（减号存相反数），乘除立刻与栈顶结算，最后把栈求和。除法向 0 取整。
// 多位数用 num = num * 10 + (c - '0')。循环结束时最后一个数也要结算，尾部空格同样触发结算。
// 换题：224 可保存累计结果和符号；772 须保存每层完整项栈及待处理运算符，或递归把括号值作为一个操作数。
static int calculate(String s) {
    Deque<Integer> st = new ArrayDeque<>();
    int num = 0;
    char sign = '+';
    for (int i = 0;
    i < s.length();
    i++) {
        char c = s.charAt(i);
        if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
        }
        if ((c != ' ' && (c < '0' || c > '9')) || i == s.length() - 1) {
            if (sign == '+') {
                st.push(num);
            } else if (sign == '-') {
                st.push(-num);
            } else if (sign == '*') {
                st.push(st.pop() * num);
            } else if (sign == '/') {
                st.push(st.pop() / num);
            }
            sign = c;
            num = 0;
        }
    }
    int ans = 0;
    while (!st.isEmpty()) {
        ans += st.pop();
    }
    return ans;
}

