// Java 常用集合、队列、堆与数组工具
class Solution {
    public boolean isValid(String s) {
        // 未闭合的左括号只能按逆序被右括号关掉，所以只压左括号。
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
                continue;
            }
            // 没有可配对的左括号，或类型对不上，都不能闭合。
            if (stack.isEmpty()) return false;
            char left = stack.pop();
            if ((c == ')' && left != '(')
            || (c == ']' && left != '[')
            || (c == '}' && left != '{')) {
                return false;
            }
        }
        // 栈空才表示每个左括号都已被对应右括号关掉。
        return stack.isEmpty();
    }
}

import java.util.*;
class Solution {
    public boolean isValidWithPriority(String s) {
        Map<Character, Character> pair = Map.of(
        ')', '(',
        ']', '[',
        '}', '{');
        // 数字越大优先级越高，外层必须不低于内层。
        Map<Character, Integer> rank = Map.of(
        '(', 1,
        '[', 2,
        '{', 3);
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (rank.containsKey(c)) {
                // 栈顶是外层；新的内层不能比外层等级更高。
                if (!stack.isEmpty() && rank.get(c) > rank.get(stack.peek())) {
                    return false;
                }
                stack.push(c);
            } else if (pair.containsKey(c)) {
                if (stack.isEmpty() || stack.pop() != pair.get(c)) {
                    return false;
                }
            } else {
                // 只接受这六种括号字符。
                return false;
            }
        }
        return stack.isEmpty();
    }
}

class Solution {
    public boolean checkValidString(String s) {
        int low = 0, high = 0;
        // 未匹配左括号的下界与上界
        for (int i = 0;
        i < s.length();
        i++) {
            char c = s.charAt(i);
            if (c == '(') {
                low++;
                high++;
            } else if (c == ')') {
                if (low > 0) {
                    low--;
                }
                high--;
            } else {
                if (low > 0) {
                    // * 尽量当右括号压低下界
                    low--;
                }
                high++;
                // * 同时可以当左括号，抬高上界
            }
            if (high < 0) {
                return false;
                // 右括号已经不可能被配平
            }
        }
        return low == 0;
    }
}

class Solution {
    public int minAddToMakeValid(String s) {
        int balance = 0, ans = 0;
        for (int i = 0;
        i < s.length();
        i++) {
            char c = s.charAt(i);
            if (c == '(') {
                balance++;
            } else {
                if (balance > 0) {
                    balance--;
                    // 用已有左括号配对
                } else {
                    ans++;
                    // 这个右括号必须补一个左括号
                }
            }
        }
        return ans + balance;
        // 剩余左括号各补一个右括号
    }
}

import java.util.*;
class Solution {
    public String minRemoveToMakeValid(String s) {
        char[] arr = s.toCharArray();
        Deque<Integer> stack = new ArrayDeque<>();
        // 未匹配左括号的下标
        boolean[] removed = new boolean[arr.length];
        for (int i = 0;
        i < arr.length;
        i++) {
            if (arr[i] == '(') {
                stack.push(i);
            } else if (arr[i] == ')') {
                if (stack.isEmpty()) {
                    removed[i] = true;
                    // 没有左括号可配，删掉这个右括号
                } else {
                    stack.pop();
                }
            }
        }
        while (!stack.isEmpty()) {
            removed[stack.pop()] = true;
            // 剩余左括号同样删掉
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0;
        i < arr.length;
        i++) {
            if (!removed[i]) {
                sb.append(arr[i]);
            }
        }
        return sb.toString();
    }
}

class Solution {
    public int minInsertions(String s) {
        int ans = 0, need = 0;
        // need：还缺的右括号个数
        for (int i = 0;
        i < s.length();
        i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if ((need & 1) == 1) {
                    ans++;
                    // 奇数个缺口无法被新左括号接上，先补一个 )
                    need--;
                }
                need += 2;
            } else {
                need--;
                if (need == -1) {
                    ans++;
                    // 多出一个 )，插入一个 (
                    need = 1;
                }
            }
        }
        return ans + need;
    }
}

class Solution {
    public int minSwaps(String s) {
        int balance = 0, minBalance = 0;
        for (int i = 0;
        i < s.length();
        i++) {
            char c = s.charAt(i);
            if (c == '[') {
                balance++;
            } else {
                balance--;
                minBalance = Math.min(minBalance, balance);
                // 记录最深的 ] 过剩
            }
        }
        return (-minBalance + 1) / 2;
        // 一次交换消掉两个失衡
    }
}

import java.util.*;
class Solution {
    public int scoreOfParentheses(String s) {
        // 栈记外层分数，cur 记当前层
        Deque<Integer> stack = new ArrayDeque<>();
        int cur = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                // 进入更深层前先保存外层并清空当前层
                stack.push(cur);
                cur = 0;
            } else {
                // 空层记 1，否则记 2*cur，再加回外层
                cur = stack.pop() + Math.max(2 * cur, 1);
            }
        }
        return cur;
    }
}

