// Java 常用集合、队列、堆与数组工具
class Solution {
    public String decodeString(String s) {
        // 进入 '[' 前，外层已经拼好的字符串要先存起来。
        Deque<StringBuilder> stringStack = new ArrayDeque<>();
        // 每个 '[' 对应它前面刚读完的重复次数。
        Deque<Integer> countStack = new ArrayDeque<>();
        StringBuilder current = new StringBuilder();
        int number = 0;
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                // 次数可能不止一位，例如 12[a]。
                number = number * 10 + (c - '0');
            } else if (c == '[') {
                countStack.push(number);
                stringStack.push(current);
                // 新的一层从空片段重新开始收集。
                number = 0;
                current = new StringBuilder();
            } else if (c == ']') {
                int repeat = countStack.pop();
                StringBuilder parent = stringStack.pop();
                // 当前层重复 repeat 次后接回外层。
                for (int i = 0;
                i < repeat;
                i++) {
                    parent.append(current);
                }
                current = parent;
            } else {
                current.append(c);
            }
        }
        return current.toString();
    }
}

import java.util.*;
class Solution {
    public String compressString(String s) {
        if (s == null || s.isEmpty()) return s;
        Deque<Character> stack = new ArrayDeque<>();
        StringBuilder compressed = new StringBuilder();
        for (char c : s.toCharArray()) {
            // 字符变化：先结算上一段连续字符。
            if (!stack.isEmpty() && stack.peek() != c) {
                compressed.append(stack.peek()).append(stack.size());
                stack.clear();
            }
            stack.push(c);
            // 相同字符继续累在栈里，size 就是次数。
        }
        // 别忘了最后一段。
        compressed.append(stack.peek()).append(stack.size());
        // 压缩后没有更短，则按题意返回原串。
        return compressed.length() < s.length() ? compressed.toString() : s;
    }
}

class Solution {
    public int calculate(String s) {
        long result = 0;
        // 已经确定、可以提交的加减部分。
        long lastTerm = 0;
        // 当前还可能继续参与乘除的最后一项。
        long number = 0;
        // 正在读取的数字。
        char operator = '+';
        // number 前面的运算符。
        for (int i = 0;
        i <= s.length();
        i++) {
            char c = i < s.length() ? s.charAt(i) : '+';
            // 末尾哨兵触发最后一次结算。
            if (i < s.length() && Character.isDigit(c)) {
                number = number * 10 + (c - '0');
                continue;
            }
            if (i < s.length() && c == ' ') {
                continue;
            }
            // 此时遇到了新的运算符，应先执行“上一轮保存的 operator”。
            switch (operator) {
                case '+':
                result += lastTerm;
                lastTerm = number;
                break;
                case '-':
                result += lastTerm;
                lastTerm = -number;
                break;
                case '*':
                lastTerm = lastTerm * number;
                break;
                case '/':
                lastTerm = lastTerm / number;
                // Java 整数除法向 0 截断。
                break;
                default:
                throw new IllegalStateException("unexpected operator");
            }
            operator = c;
            // 这个运算符留给下一轮执行。
            number = 0;
        }
        return (int) (result + lastTerm);
    }
}

import java.util.*;
class Solution {
    public int calculate(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        int ans = 0, num = 0, sign = 1;
        for (int i = 0;
        i < s.length();
        i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + c - '0';
                // 拼出多位数
            } else if (c == '+') {
                ans += sign * num;
                num = 0;
                sign = 1;
            } else if (c == '-') {
                ans += sign * num;
                // 先结算符号前的数，再把符号改成减
                num = 0;
                sign = -1;
            } else if (c == '(') {
                stack.push(ans);
                stack.push(sign);
                // 记下进入括号前的结果和这一层的符号
                ans = 0;
                sign = 1;
            } else if (c == ')') {
                ans += sign * num;
                num = 0;
                ans *= stack.pop();
                // 先乘括号前的符号，再加回外层结果
                ans += stack.pop();
            }
        }
        return ans + sign * num;
        // 表达式末尾没有运算符，补上最后一个数
    }
}

import java.util.*;
class Solution {
    public int calculate(String s) {
        return dfs(s.toCharArray(), new int[]{
            0
        }
        );
    }
    private int dfs(char[] arr, int[] idx) {
        Deque<Integer> stack = new ArrayDeque<>();
        int num = 0;
        char sign = '+';
        while (idx[0] < arr.length) {
            char c = arr[idx[0]];
            if (Character.isDigit(c)) {
                num = num * 10 + c - '0';
            }
            if (c == '(') {
                idx[0]++;
                num = dfs(arr, idx);
                // 括号内整段递归成一个数
            }
            // 运算符、右括号或最后一个字符时，按 sign 把 num 结算进栈
            if ((!Character.isDigit(c) && c != ' ') || idx[0] == arr.length - 1) {
                if (sign == '+') {
                    stack.push(num);
                } else if (sign == '-') {
                    stack.push(-num);
                } else if (sign == '*') {
                    stack.push(stack.pop() * num);
                    // 乘除优先级高，立刻和前一项合并
                } else if (sign == '/') {
                    stack.push(stack.pop() / num);
                }
                if (c == ')') {
                    break;
                    // 本层括号结束，下标留给外层继续加一
                }
                sign = c;
                num = 0;
            }
            idx[0]++;
        }
        int ans = 0;
        while (!stack.isEmpty()) {
            ans += stack.pop();
        }
        return ans;
    }
}

import java.util.Objects;
public final class Pattern132 {
    private Pattern132() {
    }
    public static boolean contains(int[]a){
        Objects.requireNonNull(a);
        int[]stack=new int[a.length];
        int size=0;
        long second=Long.MIN_VALUE;
        for(int i=a.length-1;i>=0;i--){
            if(a[i]<second)return true;
            while(size>0&&a[i]>stack[size-1])second=Math.max(second,stack[--size]);
            stack[size++]=a[i];
        }
        return false;
    }
    private static boolean oracle(int[]a){
        for(int i=0;i<a.length;i++)for(int j=i+1;j<a.length;j++)for(int k=j+1;k<a.length;k++)if(a[i]<a[k]&&a[k]<a[j])return true;
        return false;
    }
    public static void main(String[]args){
        int cases=0;
        for(int n=0;n<=8;n++){
            int count=1<<(2*n);
            for(int mask=0;mask<count;mask++){
                int[]a=new int[n];
                int x=mask;
                for(int i=0;i<n;i++){
                    a[i]=(x&3)-2;
                    x>>>=2;
                }
                if(contains(a)!=oracle(a))throw new AssertionError();
                cases++;
            }
        }
        int[][]extra={{
            Integer.MIN_VALUE,Integer.MAX_VALUE,0
        }
        ,{3,1,4,2},{1,2,3,4},{1,0,1,-4,-3},{2,2,2},{Integer.MIN_VALUE,Integer.MAX_VALUE,Integer.MIN_VALUE}};
        for(int[]a:extra)if(contains(a)!=oracle(a))throw new AssertionError();
        int[]descending=new int[100000];
        for(int i=0;i<descending.length;i++)descending[i]=descending.length-i;
        if(contains(descending))throw new AssertionError();
        System.out.println("PASS 132 triples oracle cases="+cases+" strict duplicates/int extremes/100000 descending; linear stack");
    }
}

import java.util.*;
public final class DistinctSubsequence {
    public static String smallest(String s){
        Objects.requireNonNull(s);
        int[] remaining=new int[26];
        for(int i=0;i<s.length();i++){
            int x=s.charAt(i)-'a';
            if(x<0||x>=26)throw new IllegalArgumentException("lowercase a-z only");
            remaining[x]++;
        }
        boolean[] included=new boolean[26];
        char[] stack=new char[26];
        int size=0;
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            int x=c-'a';
            remaining[x]--;
            if(included[x])continue;
            while(size>0&&stack[size-1]>c&&remaining[stack[size-1]-'a']>0)included[stack[--size]-'a']=false;
            stack[size++]=c;
            included[x]=true;
        }
        return new String(stack,0,size);
    }
    static String oracle(String s){
        Set<Character> chars=new HashSet<>();
        for(char c:s.toCharArray())chars.add(c);
        String best=null;
        for(int bits=0;bits<(1<<s.length());bits++){
            if(Integer.bitCount(bits)!=chars.size())continue;
            Set<Character> used=new HashSet<>();
            StringBuilder out=new StringBuilder();
            boolean valid=true;
            for(int i=0;i<s.length();i++)if((bits&(1<<i))!=0){
                char c=s.charAt(i);
                if(!used.add(c)){
                    valid=false;
                    break;
                }
                out.append(c);
            }
            if(valid){
                String now=out.toString();
                if(best==null||now.compareTo(best)<0)best=now;
            }
        }
        return best==null?"":best;
    }
    static int count;
    static void enumerate(String s,int left){
        if(!smallest(s).equals(oracle(s)))throw new AssertionError(s);
        count++;
        if(left>0)for(char c='a';c<='c';c++)enumerate(s+c,left-1);
    }
    public static void main(String[] args){
        enumerate("",8);
        if(!smallest("cbacdcbc").equals("acdb")||!smallest("bcabc").equals("abc"))throw new AssertionError();
        System.out.println("PASS "+count+" exhaustive abc strings versus ALL subsequences; source LC316 examples");
    }
}

