public final class ValidateStackOrder {
    /** LC946: pushed contains unique values; popped must be a permutation of them. */
    public static boolean valid(int[] pushed,int[] popped){
        Objects.requireNonNull(pushed);
        Objects.requireNonNull(popped);
        if(pushed.length!=popped.length)return false;
        Set<Integer> unique=new HashSet<>();
        for(int x:pushed)if(!unique.add(x))throw new IllegalArgumentException("LC946 requires distinct pushed values");
        Set<Integer> remaining=new HashSet<>(unique);
        for(int x:popped)if(!remaining.remove(x))return false;
        int[] stack=new int[pushed.length];
        int size=0,j=0;
        for(int x:pushed){
            stack[size++]=x;
            while(size>0 && j<popped.length && stack[size-1]==popped[j]){
                size--;
                j++;
            }
        }
        return j==popped.length && size==0;
    }
    private static void generate(int n,int pushed,List<Integer> stack,List<Integer> out,Set<List<Integer>> possible){
        if(out.size()==n){
            possible.add(List.copyOf(out));
            return;
        }
        if(pushed<n){
            stack.add(pushed);
            generate(n,pushed+1,stack,out,possible);
            stack.remove(stack.size()-1);
        }
        if(!stack.isEmpty()){
            int x=stack.remove(stack.size()-1);
            out.add(x);
            generate(n,pushed,stack,out,possible);
            out.remove(out.size()-1);
            stack.add(x);
        }
    }
    private static long permutations(int[] a,int at,Set<List<Integer>> possible){
        if(at==a.length){
            int[] pushed=new int[a.length];
            List<Integer> key=new ArrayList<>();
            for(int i=0;i<a.length;i++){
                pushed[i]=i;
                key.add(a[i]);
            }
            if(valid(pushed,a)!=possible.contains(key))throw new AssertionError(key.toString());
            return 1;
        }
        long count=0;
        for(int i=at;i<a.length;i++){
            int x=a[at];
            a[at]=a[i];
            a[i]=x;
            count+=permutations(a,at+1,possible);
            x=a[at];
            a[at]=a[i];
            a[i]=x;
        }
        return count;
    }
    public static void main(String[] args){
        long count=0;
        for(int n=0;n<=8;n++){
            Set<List<Integer>> possible=new HashSet<>();
            generate(n,0,new ArrayList<>(),new ArrayList<>(),possible);
            int[] a=new int[n];
            for(int i=0;i<n;i++)a[i]=i;
            count+=permutations(a,0,possible);
        }
        if(valid(new int[]{
            1,2
        }
        ,new int[]{
            1,1
        }
        )||valid(new int[]{
            1
        }
        ,new int[]{
            2
        }
        )||valid(new int[]{
            1
        }
        ,new int[0]))throw new AssertionError();
        try{
            valid(new int[]{
                1,1
            }
            ,new int[]{
                1,1
            }
            );
            throw new AssertionError();
        }
        catch(IllegalArgumentException expected){
        }
        System.out.println("PASS "+count+" permutations vs independently enumerated all legal push/pop schedules; empty/invalid sets/distinct-key contract");
    }
